SELECT genre_character_id
FROM genre_character
WHERE user_id = #{userId} AND genre_character_group_id = #{genreCharacterGroupId}

SELECT COUNT(*)
FROM genre_character
WHERE user_id = #{userId} AND genre_character_group_id = #{genreCharacterGroupId}

SELECT COUNT(DISTINCT figure_id)
FROM figure_character_map
WHERE user_id = #{userId} AND genre_character_id = #{genreCharacterId}

mapper.insert:
INSERT INTO figure_character_map (user_id, figure_id, genre_character_id)
SELECT DISTINCT l.user_id, l.figure_id, #{fallbackId}
FROM figure_character_map l
WHERE l.user_id = #{userId}
  AND l.genre_character_id = #{genreCharacterId}
  AND NOT EXISTS (
      SELECT 1 FROM figure_character_map o
      WHERE o.user_id = l.user_id AND o.figure_id = l.figure_id
        AND o.genre_character_id <> #{genreCharacterId}
  )
